using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change #1: Discriminator property renamed to "$type".
            // Preserve EF8 format so existing 500K documents remain readable.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change #2: id format changed from "EntityName|Key" to just "Key".
            // Preserve EF8 "Product|{Id}" format for existing documents.
            entity.HasKey(p => p.Id);
            entity.Property(p => p.Id).ToJsonProperty("id");
            entity.UseETagConcurrency();

            // EF Core 9 breaking change #3: HasIndex() is no longer supported for Cosmos.
            // Cosmos indexing is managed via container indexing policy, not EF model config.
            // Removed: entity.HasIndex(p => p.Sku);
        });
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // EF Core 9 breaking change #4: Sync I/O now throws by default.
        // Either switch to async APIs or opt-in to sync (see CosmosQuery.cs).
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

